    /*
     * Editing a tbl_transactions
     */
    function edit($id)
    {   
        // check if the tbl_transactions exists before trying to edit it
        $data['tbl_transactions'] = $this->Tbl_transactions_model->get_tbl_transactions($id);
        
        if(isset($data['tbl_transactions']['id']))
        {
            $this->load->library('form_validation');

			$this->form_validation->set_rules('transactions_name','transactions Name','max_length[255]');
			$this->form_validation->set_rules('real_name','Real Name','max_length[255]');
			$this->form_validation->set_rules('group','Group','integer');
			$this->form_validation->set_rules('dara_rate','Dara Rate','integer');
			$this->form_validation->set_rules('akhar_rate','Akhar Rate','integer');
			$this->form_validation->set_rules('owner_name','Owner Name','max_length[255]');
			$this->form_validation->set_rules('mobile','Mobile','integer');
			$this->form_validation->set_rules('updated_by','Updated By','integer');
		
			if($this->form_validation->run())     
            {   
                $params = array(
					'transactions_name' => $this->input->post('transactions_name'),
					'real_name' => $this->input->post('real_name'),
					'group' => $this->input->post('group'),
					'dara_rate' => $this->input->post('dara_rate'),
					'akhar_rate' => $this->input->post('akhar_rate'),
					'owner_name' => $this->input->post('owner_name'),
					'mobile' => $this->input->post('mobile'),
					'updated_by' => $this->input->post('updated_by'),
					'updated_date' => $this->input->post('updated_date'),
					'dara_commision' => $this->input->post('dara_commision'),
					'akhar_commission' => $this->input->post('akhar_commission'),
					'tp_akhar_commission' => $this->input->post('tp_akhar_commission'),
					'rebate' => $this->input->post('rebate'),
					'tp_r' => $this->input->post('tp_r'),
					'hissa' => $this->input->post('hissa'),
					'address' => $this->input->post('address'),
                );

                $this->Tbl_transactions_model->update_tbl_transactions($id,$params);            
                redirect('tbl_transactions/index');
            }
            else
            {
                $data['_view'] = 'tbl_transactions/edit';
                $this->load->view('layouts/main',$data);
            }
        }
        else
            show_error('The tbl_transactions you are trying to edit does not exist.');
    } 

    /*
     * Deleting tbl_transactions
     */
    function remove($id)
    {
        $tbl_transactions = $this->Tbl_transactions_model->get_tbl_transactions($id);
		$shift = $tbl_transactions['shift_id'];
		$party = $tbl_transactions['party_id'];
		$date = date('Y-m-d',strtotime($tbl_transactions['t_date']));
        $tbl_transaction = $this->Tbl_transactions_model->get_party_entry($shift,$party,$date);
		// check if the tbl_transactions exists before trying to delete it
		//echo '<pre>'; print_r(count($tbl_transaction)); echo '</pre>'; die;
        if(isset($tbl_transactions['id']))
        {
			$hisab_delete = $this->Tbl_transactions_model->delete_hisab_transaction($tbl_transactions['shift_id'],$tbl_transactions['party_id'],$tbl_transactions['t_date'],$id); 
            //if($hisab_delete){
		//	print_r($hisab_delete); die;
		if($hisab_delete){
			redirect('/view_transactions');
		}
		else{
			show_error('Cannot delete.!!');
		}
				//$this->Tbl_transactions_model->delete_tbl_transactions($id);
            
        //}
	}
        else
            show_error('The tbl_transactions you are trying to delete does not exist.');
    }    
